<script setup lang="ts">
import {ref} from 'vue'
type Entry={id:number,name:string,size:number,type:string}
const entries=ref<Entry[]>([]),feedback=ref(''),dragging=ref(false),input=ref<HTMLInputElement>()
let nextId=0
function accept(files:File[]){let added=0;const rejected:string[]=[];for(const file of files){if(!/\.(pdf|txt)$/i.test(file.name)||file.size>2*1024*1024){rejected.push(file.name);continue}entries.value.push({id:++nextId,name:file.name,size:file.size,type:file.type||'Unknown MIME'});added++}feedback.value=`${added} files added locally.${rejected.length?' Rejected: '+rejected.join(', ')+'. Use PDF/TXT up to 2 MiB each.':''}`;if(input.value)input.value.value=''}
function change(event:Event){accept(Array.from((event.target as HTMLInputElement).files||[]))}
function drop(event:DragEvent){dragging.value=false;accept(Array.from(event.dataTransfer?.files||[]))}
function remove(id:number){entries.value=entries.value.filter(x=>x.id!==id);feedback.value='File removed from the local list.';input.value?.focus()}
function clear(){entries.value=[];feedback.value='Local list cleared.';if(input.value)input.value.value=''}
function samples(){entries.value.push({id:++nextId,name:'sample-notes.txt',size:128,type:'text/plain'},{id:++nextId,name:'sample-brief.pdf',size:4096,type:'application/pdf'});feedback.value='Fictitious metadata added. No files generated or uploaded.'}
</script>
<template><section class="attachment-usage" aria-label="Attachment demonstration"><p>Local metadata only. Files are not read, previewed or uploaded. Use Add fictitious files to try the list without selecting private files.</p><div class="drop" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="drop"><label>Select local PDF or TXT files<input ref="input" type="file" multiple accept=".pdf,.txt" aria-describedby="attachment-guide-rules" @change="change"></label><p id="attachment-guide-rules">Drop files here or use the native picker. Up to 2 MiB each. The filename check is a demo convenience, not security validation.</p></div><div class="actions"><button type="button" @click="samples">Add fictitious files</button><button type="button" @click="clear">Clear local list</button></div><ul v-if="entries.length"><li v-for="entry in entries" :key="entry.id"><div><strong>{{entry.name}}</strong><small>{{entry.size}} bytes · {{entry.type}} · Local only</small></div><button type="button" :aria-label="`Remove ${entry.name} from local list`" @click="remove(entry.id)">Remove</button></li></ul><p v-else>No local files selected.</p><p role="status">{{feedback}}</p></section></template>
<style scoped>
.attachment-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.drop{padding:20px;border:2px dashed var(--vp-c-divider);border-radius:8px;transition:background 150ms ease-out}.drop.dragging{background:var(--vp-c-brand-soft)}label{display:flex;flex-direction:column;gap:12px}input{max-width:100%;font-size:14px}input::file-selector-button,button{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft);color:var(--vp-c-text-1)}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}ul{list-style:none!important;padding:0!important}li{display:flex;justify-content:space-between;gap:12px;align-items:start;padding:16px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:12px 0!important;animation:file-enter 160ms ease-out}li div{min-width:0;overflow-wrap:anywhere}small{display:block}li button{flex-shrink:0}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@keyframes file-enter{from{opacity:.4;translate:0 3px}to{opacity:1;translate:0 0}}@media(prefers-reduced-motion:reduce){li{animation:none}.drop{transition:none}}
</style>
